WFJ.Data.add("gossip", {
  ["a801e703c994eac2"] = { "%s implora che si ponga fine alle sue sofferenze.", "." },
  ["a8074aecb09c586d"] = { "%s e il predone Kerr si lanciano nella battaglia...", "." },
  ["a80c17cc5ab04028"] = { "Percepisco il tuo arrivo da parecchio tempo, {name}. Era scritto nella trama delle stelle.", "." },
  ["a810f16c872aca92"] = { "Ho fallito ancora una volta...", "." },
  ["a81e8184a5d494b4"] = { "La battaglia va bene. Le forze del Flagello sembrano indebolite. Credo che sia solo questione di tempo prima di ricacciarle dalle nostre coste. Rivolgerò la mia magia a te, per aiutarti in questa lotta.", "." },
  ["a824598994c1bbfc"] = { "Proprio così, ehm, <ragazzo/ragazza>: tutto il materiale bellico viene trasportato a ⟦Silithus=Silitus⟧ e l'ultimo carico dovrebbe arrivare entro $2113w giorni. Dopo, non ci resterà che aspettare e vedere chi farà avanti <un/una> <eroe/eroina> per ricomporre lo Scettro delle Sabbie Mutevoli e suonare il gong sullo Scarab Dais. Solo allora la guerra aprirà le porte di ⟦Ahn'Qiraj=Ahn'qiraj⟧.", "." },
  ["a8259f3f79551194"] = { "La tua abilità supera la mia, ma ho sentito dire che il vecchio Heming, a ⟦Booty Bay=Baia del Bottino⟧, ha delle copie di «Conosci il Tuo Branzino». Di certo ti aiuterà a migliorare la tua abilità.", "." },
  ["a82741f07038b0fe"] = { "Ti prego, non disturbarmi... Quelli come te sono tutti uguali...", "." },
  ["a82f82ccebda868c"] = { "Iuhuu, si parte! Tutti hanno raccolto tutto, e proprio ora viene trasportato in zeppelin fino a ⟦Silithus=Silitus⟧. L'ultima parte dovrebbe arrivare in meno di $2113w giorni. Quando tutto sarà là e lo scettro sarà ricomposto, potrà iniziare la guerra contro quei sudici insetti. Come si dice: «Spediscilo!»", "." },
  ["a82fc79088e60cda"] = { "Salute, <signore/signorina>. Sono Nyrill, apprendista del maestro Xylem. Se hai qualche questione, non esitare a parlarne con il maestro.\n\nSarò qui al tuo servizio quando vorrai tornare ai piedi della montagna.", "." },
  ["a8328af99936610f"] = { "Noi essere liberi! Grazie, piccoli mingherlini.", "." },
  ["a83abb850fd752a4"] = { "Sì, credo che tu abbia del potenziale. Forse posso mostrarti un paio di cose.", "." },
  ["a83d7f9dde139e05"] = { "Cerco uno Stregone grande e potente.", "." },
  ["a83fcc269cc9b080"] = { "Maestro Vectus, percepisco qualcosa di strano in questo contenitore...", "." },
  ["a847d6867a629ff2"] = { "I lupi vengono da questa parte, come se fuggissero da... qualcosa.", "." },
  ["a85856470b6e96c6"] = { "In parole semplici, è così.\n\nI Terrigeni hanno le caratteristiche fisiche di un umanoide di statura minore, ma sono composti dei vari minerali del nucleo di pietra di Azeroth. La loro struttura massimizza forza e vigore senza sacrificare la capacità di elaborazione cognitiva. La loro pelle e la loro muscolatura sono quasi invulnerabili ai danni fisici, e con modifiche minime i Terrigeni mostrano una notevole resistenza alle forze magiche indesiderate.", "." },
  ["a859c47d9ecfd5c0"] = { "Birra Scura di ⟦Southshore=Riva del Sud⟧, quanto ti amo? Lascia che conti i modi...", "." },
  ["a867d6bd99e3a344"] = { "Dobbiamo riempire questo carro entro la fine della giornata. Quindi tornate al lavoro. Forza, svelti!", "." },
  ["a86ecf4ee28adb1c"] = { "Il ⟦Iceblood Graveyard=Cimitero di Brinarossa⟧ è stato conquistato dall'⟦Horde=Orda⟧!", "." },
  ["a87bcb8e3830903d"] = { "Lascia le tue battaglie o le tue commissioni, e guarda la mia incredibile merce! Solo per poco tempo a ⟦Darkshire=Borgoscuro⟧... sia lodata la Luce per questo.", "." },
  ["a88032d6f1245132"] = { "Salute, {name}. Sono ⟦Johnny McWeaksauce=Johnny Salsaforte⟧. Gli sviluppatori mi usano come strumento per svolgere funzioni specifiche a scopo di test. Per questo periodo di test sono impostato per fare due cose precise:\n\n(1) Segnarti come chi ha completato la missione di sintonia di Naxxramas, così da poter accettare la missione successiva, \"Echoes of War\", dal comandante Eligor Dawnbringer. Devi prima completare quella missione per accedere alle missioni del tuo set di armatura Tier 3.\n\n(2) Teletrasportarti a Naxxramas.\n\nDi cosa hai bisogno?", "." },
  ["a88abadbc30af46b"] = { "Cos'è questo rumore?", "." },
  ["a88ca7cb776ae16c"] = { "Non abbocca niente....", "." },
  ["a892886186ad4819"] = { "Se tu non parla con Mizzle, tu non diventa re! Parla con Mizzle l'Astuto!", "." },
  ["a8a520e8655729fb"] = { "Usurpatore?", "." },
  ["a8a59d52a5f2dbf4"] = { "Cosa!?", "." },
  ["a8a7efd1db1cc9eb"] = { "Silenzio! Credi che i nostri draghi appestati si schiuderanno e si addestreranno da soli?", "." },
  ["a8aa18db2d318fa4"] = { "Iniziamo una nuova battaglia, e stavolta battiamo l'⟦Alliance=Alleanza⟧!", "." },
  ["a8ac23a66ab038fa"] = { "Un po' di abilità ce l'hai, eh. Abbastanza da imparare qualcosa, scommetto. Vediamo cosa posso insegnarti, d'accordo?", "." },
  ["a8bd075f304a69ba"] = { "C'è chi dice che forza e coraggio siano ciò che serve di più al successo di un esercito. Ed è vero! Ma un esercito ha anche bisogno di provviste per mantenersi in forma, e il mio compito è assicurarmi che abbia ciò che gli serve.", "." },
  ["a8bf4aae97e3117f"] = { "Ho un'altra domanda.", "." },
  ["a8bffdba16cf16cc"] = { "Se ti serve una locanda, la Stonefire Inn è dove devi andare. La trovi subito a sinistra dell'ingresso di ⟦Ironforge=Forgiardente⟧ se stai arrivando, o a destra se stai uscendo.\n\nOh, e se vai da quella parte, di' loro di tenermi pronto un boccale.", "." },
  ["a8cca70c71c66b52"] = { "Direttamente dalle rigogliose foreste di Elwynn, prendete qui la vostra frutta fresca.", "." },
  ["a8cf7714985c8b56"] = { "Gryfe fa suo lavoro! Gryfe va ora!!!", "." },
  ["a8e94a16f047abf4"] = { "Bah! Torno al lavoro! Grazie mille, Belm.", "." },
  ["a8ebc9ebf7300421"] = { "Basta! Ne ho abbastanza di aiutarti. È ora di regolare i conti sul campo di battaglia!", "." },
  ["a8ec40e23913e24b"] = { "⟦Hoary Templar=Templare Hoary⟧! Possiedo il tuo stemma di richiamo. Rispondi alla mia chiamata!", "." },
  ["a8f21ce977d7d6b5"] = { "Ma così non incroceremmo i flussi? Non è una cosa molto brutta?", "." },
  ["a8f62bdc751dda2e"] = { "Hip hip... urrrrrà...", "." },
  ["a8fd97572c4d133f"] = { "Grazie, {name}. Il mio tormento è finalmente finito.", "." },
})
